statement:
Let $\mathcal{D}$ be a triangulated category. Let $E, K$ be objects
of $\mathcal{D}$. The following are equivalent
\begin{enumerate}
\item $\Hom(E, K[i]) = 0$ for all $i \in \mathbf{Z}$,
\item $\Hom(E', K) = 0$ for all $E' \in \langle E \rangle$.
\end{enumerate}

statement_tex:
\label{lemma-right-orthogonal}
Let $\mathcal{D}$ be a triangulated category. Let $E, K$ be objects
of $\mathcal{D}$. The following are equivalent
\begin{enumerate}
\item $\Hom(E, K[i]) = 0$ for all $i \in \mathbf{Z}$,
\item $\Hom(E', K) = 0$ for all $E' \in \langle E \rangle$.
\end{enumerate}

\label{lemma-descending-property-separated}
The property $\mathcal{P}(f) =$``$f$ is separated''
is fpqc local on the base.

\label{lemma-regular-point-on-curve}
Let $k$ be a field. Let $X$ be a curve over $k$. Let $x \in X$ be a closed
point. We think of $x$ as a (reduced) closed subscheme of $X$ with sheaf
of ideals $\mathcal{I}$. The following are equivalent
\begin{enumerate}
\item $\mathcal{O}_{X, x}$ is regular,
\item $\mathcal{O}_{X, x}$ is normal,
\item $\mathcal{O}_{X, x}$ is a discrete valuation ring,
\item $\mathcal{I}$ is an invertible $\mathcal{O}_X$-module,
\item $x$ is an effective Cartier divisor on $X$.
\end{enumerate}
If $k$ is perfect or if $\kappa(x)$ is separable over $k$,
these are also equivalent to
\begin{enumerate}
\item[(6)] $X \to \Spec(k)$ is smooth at $x$.
\end{enumerate}

\label{lemma-apply-Leray}
Let $f : X \to Y$ be a morphism of ringed spaces.
Let $\mathcal{F}$ be an $\mathcal{O}_X$-module.
\begin{enumerate}
\item If $R^qf_*\mathcal{F} = 0$ for $q > 0$, then
$H^p(X, \mathcal{F}) = H^p(Y, f_*\mathcal{F})$ for all $p$.
\item If $H^p(Y, R^qf_*\mathcal{F}) = 0$ for all $q$ and $p > 0$, then
$H^q(X, \mathcal{F}) = H^0(Y, R^qf_*\mathcal{F})$ for all $q$.
\end{enumerate}

\label{lemma-direct-sum-from-product-essentially-constant}
Let $\mathcal{I}$ be a filtered category. Let $\mathcal{A}$
be an additive, Karoubian category. Let $F : \mathcal{I} \to \mathcal{A}$ and
$G : \mathcal{I} \to \mathcal{A}$ be functors. The following are equivalent
\begin{enumerate}
\item $F \oplus G : \mathcal{I} \to \mathcal{A}$
is essentially constant, and
\item $F$ and $G$ are essentially constant.
\end{enumerate}

\label{lemma-descending-property-universally-submersive}
The property $\mathcal{P}(f) =$``$f$ is universally submersive''
is fpqc local on the base.

\label{lemma-descending-property-relative-dimension-d}
The property $\mathcal{P}(f) =$``$f$ is locally of finite type
of relative dimension $d$'' is fpqc local on the base.

\label{lemma-third-object-zero}
Let $\mathcal{D}$ be a pre-triangulated category.
Let $f : X \to Y$ be a morphism of $\mathcal{D}$.
The following are equivalent
\begin{enumerate}
\item $f$ is an isomorphism,
\item $(X, Y, 0, f, 0, 0)$ is a distinguished triangle, and
\item for any distinguished triangle $(X, Y, Z, f, g, h)$ we have $Z = 0$.
\end{enumerate}

statement:
\begin{reference}
Part (1) is the main theorem of \cite{Scheiderer}.
\end{reference}
Let $X$ be a spectral space of Krull dimension $d$.
Let $\mathcal{F}$ be an abelian sheaf on $X$.
\begin{enumerate}
\item $H^q(X, \mathcal{F}) = 0$ for $q > d$,
\item $H^d(X, \mathcal{F}) \to H^d(U, \mathcal{F})$ is surjective
for every quasi-compact open $U \subset X$,
\item $H^q_Z(X, \mathcal{F}) = 0$ for $q > d$ and any constructible
closed subset $Z \subset X$.
\end{enumerate}

statement_tex:
\label{proposition-cohomological-dimension-spectral}
\begin{reference}
Part (1) is the main theorem of \cite{Scheiderer}.
\end{reference}
Let $X$ be a spectral space of Krull dimension $d$.
Let $\mathcal{F}$ be an abelian sheaf on $X$.
\begin{enumerate}
\item $H^q(X, \mathcal{F}) = 0$ for $q > d$,
\item $H^d(X, \mathcal{F}) \to H^d(U, \mathcal{F})$ is surjective
for every quasi-compact open $U \subset X$,
\item $H^q_Z(X, \mathcal{F}) = 0$ for $q > d$ and any constructible
closed subset $Z \subset X$.
\end{enumerate}

\label{lemma-hom-into-torsion-free}
Let $R$ be a domain. Let $M$, $N$ be $R$-modules.
If $N$ is torsion free, so is $\Hom_R(M, N)$.

\label{proposition-connected-component}
Let $G$ be a group scheme over a field $k$. There exists a canonical closed
subgroup scheme $G^0 \subset G$ with the following properties
\begin{enumerate}
\item $G^0 \to G$ is a flat closed immersion,
\item $G^0 \subset G$ is the connected component of the identity,
\item $G^0$ is geometrically irreducible, and
\item $G^0$ is quasi-compact.
\end{enumerate}

\label{lemma-ampleness-in-terms-of-degrees-components}
Let $k$ be a field. Let $X$ be a proper scheme of dimension $\leq 1$
over $k$. Let $\mathcal{L}$ be an invertible $\mathcal{O}_X$-module.
Let $C_i \subset X$, $i = 1, \ldots, t$ be the irreducible components
of dimension $1$. The following are equivalent:
\begin{enumerate}
\item $\mathcal{L}$ is ample, and
\item $\deg(\mathcal{L}|_{C_i}) > 0$ for $i = 1, \ldots, t$.
\end{enumerate}

\label{lemma-composition-regular-immersion}
Let $i : Z \to Y$ and $j : Y \to X$ be immersions of schemes.
\begin{enumerate}
\item If $i$ and $j$ are regular immersions, so is $j \circ i$.
\item If $i$ and $j$ are Koszul-regular immersions, so is $j \circ i$.
\item If $i$ and $j$ are $H_1$-regular immersions, so is $j \circ i$.
\item If $i$ is an $H_1$-regular immersion and $j$ is a quasi-regular
immersion, then $j \circ i$ is a quasi-regular immersion.
\end{enumerate}

statement:
Let $X$ be an irreducible scheme over the field $k$. Let $\xi \in X$
be its generic point. The following are equivalent:
\begin{enumerate}
\item $X$ is geometrically irreducible over $k$;
\item $\kappa(\xi)$ is geometrically irreducible over $k$;
\item the separable algebraic closure of $k$ in $\kappa(\xi)$ is equal to $k$.
\end{enumerate}

statement_tex:
\label{lemma-geometrically-irreducible-function-field}
Let $X$ be an irreducible scheme over the field $k$. Let $\xi \in X$
be its generic point. The following are equivalent:
\begin{enumerate}
\item $X$ is geometrically irreducible over $k$;
\item $\kappa(\xi)$ is geometrically irreducible over $k$;
\item the separable algebraic closure of $k$ in $\kappa(\xi)$ is equal to $k$.
\end{enumerate}

\label{lemma-locally-finite-presentation-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally of finite presentation''
is fppf local on the source.

\label{lemma-perfect}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $E$ be an object of $D(\mathcal{O}_X)$.
The following are equivalent
\begin{enumerate}
\item $E$ is perfect, and
\item $E$ is pseudo-coherent and locally has finite tor dimension.
\end{enumerate}

\label{lemma-tor-amplitude}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $E$ be an object of $D(\mathcal{O}_X)$.
Let $a, b \in \mathbf{Z}$ with $a \leq b$. The following are equivalent
\begin{enumerate}
\item $E$ has tor-amplitude in $[a, b]$.
\item $E$ is represented by a complex
$\mathcal{E}^\bullet$ of flat $\mathcal{O}_X$-modules with
$\mathcal{E}^i = 0$ for $i \not \in [a, b]$.
\end{enumerate}

\label{lemma-essentially-constant-into-karoubian}
Let $\mathcal{I}$ be a category, let $\mathcal{A}$ be a pre-additive
Karoubian category, and let $M : \mathcal{I} \to \mathcal{A}$ be a diagram.
\begin{enumerate}
\item Assume $\mathcal{I}$ is filtered. The following are equivalent
\begin{enumerate}
\item $M$ is essentially constant,
\item $X = \colim M$ exists and there exists a cofinal filtered subcategory
$\mathcal{I}' \subset \mathcal{I}$ and for $i' \in \Ob(\mathcal{I}')$
a direct sum decomposition $M_{i'} = X_{i'} \oplus Z_{i'}$ such that
$X_{i'}$ maps isomorphically to $X$ and $Z_{i'}$ to zero in $M_{i''}$
for some $i' \to i''$ in $\mathcal{I}'$.
\end{enumerate}
\item Assume $\mathcal{I}$ is cofiltered. The following are equivalent
\begin{enumerate}
\item $M$ is essentially constant,
\item $X = \lim M$ exists and there exists an initial cofiltered subcategory
$\mathcal{I}' \subset \mathcal{I}$ and for $i' \in \Ob(\mathcal{I}')$
a direct sum decomposition $M_{i'} = X_{i'} \oplus Z_{i'}$
such that $X$ maps isomorphically to $X_{i'}$ and $M_{i''} \to Z_{i'}$
is zero for some $i'' \to i'$ in $\mathcal{I}'$.
\end{enumerate}
\end{enumerate}

\label{lemma-Karoubian-dual}
In a Karoubian additive monoidal category every summand
of an object which has a left dual has a left dual.

\label{lemma-universal-effective-epimorphism-affine}
Let $\{f_i : X_i \to X\}_{i \in I}$ be a family of morphisms of affine schemes.
The following are equivalent
\begin{enumerate}
\item for any quasi-coherent $\mathcal{O}_X$-module $\mathcal{F}$ we have
$$
\Gamma(X, \mathcal{F}) =
\text{Equalizer}\left(
\xymatrix{
\prod\nolimits_{i \in I} \Gamma(X_i, f_i^*\mathcal{F})
\ar@<1ex>[r] \ar@<-1ex>[r] &
\prod\nolimits_{i, j \in I}
\Gamma(X_i \times_X X_j, (f_i \times f_j)^*\mathcal{F})
}
\right)
$$
\item $\{f_i : X_i \to X\}_{i \in I}$ is a universal effective epimorphism
(Sites, Definition \ref{sites-definition-universal-effective-epimorphisms})
in the category of affine schemes.
\end{enumerate}

statement:
Let $f : A \to B$ be an \'etale homomorphism of local rings.
Then there exist $f, g \in A[t]$ such that
\begin{enumerate}
\item $B' = A[t]_g/(f)$ is standard \'etale -- see (a) and (b) above, and
\item $B$ is isomorphic to a localization of $B'$ at a prime.
\end{enumerate}

statement_tex:
\label{theorem-structure-etale}
Let $f : A \to B$ be an \'etale homomorphism of local rings.
Then there exist $f, g \in A[t]$ such that
\begin{enumerate}
\item $B' = A[t]_g/(f)$ is standard \'etale -- see (a) and (b) above, and
\item $B$ is isomorphic to a localization of $B'$ at a prime.
\end{enumerate}

\label{lemma-perfect-independent-representative}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $E$ be an object of $D(\mathcal{O}_X)$.
\begin{enumerate}
\item If there exists an open covering $X = \bigcup U_i$ and
strictly perfect complexes $\mathcal{E}_i^\bullet$ on $U_i$
such that $\mathcal{E}_i^\bullet$ represents $E|_{U_i}$ in
$D(\mathcal{O}_{U_i})$, then $E$ is perfect.
\item If $E$ is perfect, then any complex representing $E$ is perfect.
\end{enumerate}

\label{lemma-map-homology-homotopy}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item If the maps $f, g : A_\bullet \to B_\bullet$ are
homotopic, then the induced maps $H_i(f)$ and $H_i(g)$
are equal.
\item If the map $f : A_\bullet \to B_\bullet$ is a homotopy
equivalence, then $f$ is a quasi-isomorphism.
\end{enumerate}

\label{lemma-reduced-quotient-regular-ring-dim-2}
Let $(A, \mathfrak m)$ be a regular local ring of dimension $2$.
Let $I \subset \mathfrak m$ be an ideal.
\begin{enumerate}
\item If $A/I$ is reduced, then $I = (0)$, $I = \mathfrak m$, or
$I = (f)$ for some nonzero $f \in \mathfrak m$.
\item If $A/I$ has depth $1$, then $I = (f)$ for some nonzero
$f \in \mathfrak m$. 
\end{enumerate}

\label{lemma-S1-no-embedded}
Let $X$ be a locally Noetherian scheme.
Let $\mathcal{F}$ be a coherent sheaf on $X$.
Then the following are equivalent:
\begin{enumerate}
\item $\mathcal{F}$ has no embedded associated points, and
\item $\mathcal{F}$ has property $(S_1)$.
\end{enumerate}

\label{lemma-check-rank-on-affines}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. Let $r$ be a cardinal. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ has rank $r$,
\item for all $U \subset X$ nonempty affine open $\mathcal{F}(U)$
is an $\mathcal{O}_X(U)$-module of rank $r$, and
\item for some $U \subset X$ nonempty affine open $\mathcal{F}(U)$
is an $\mathcal{O}_X(U)$-module of rank $r$.
\end{enumerate}

\label{lemma-henselization-local-ring}
\begin{slogan}
Compatibility henselization of pairs and of local rings.
\end{slogan}
The functor of Lemma \ref{lemma-henselization} associates to a local ring
$(A, \mathfrak m)$ its henselization.

\label{proposition-brown}
\begin{reference}
\cite[Theorem 4.1]{Neeman-Grothendieck}.
\end{reference}
Let $\mathcal{D}$ be a triangulated category with direct sums which is
compactly generated. Let $F : \mathcal{D} \to \mathcal{D}'$ be an
exact functor of triangulated categories which transforms direct sums
into direct sums. Then $F$ has an exact right adjoint.

\label{lemma-syntomic-syntomic-local-source}
The property $\mathcal{P}(f)=$``$f$ is syntomic''
is syntomic local on the source.

\label{lemma-map-cohomology-homotopy-cochain}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item If the maps $f, g : A^\bullet \to B^\bullet$ are
homotopic, then the induced maps $H^i(f)$ and $H^i(g)$
are equal.
\item If $f : A^\bullet \to B^\bullet$ is a homotopy equivalence,
then $f$ is a quasi-isomorphism.
\end{enumerate}

\label{lemma-node-etale-local}
Let $k$ be a field. Let $X$ be a locally algebraic
$k$-scheme of dimension $1$. Let $Y \to X$ be an \'etale morphism.
Let $y \in Y$ be a point with image $x \in X$. The following are equivalent
\begin{enumerate}
\item $x$ is a closed point of $X$ and a node, and
\item $y$ is a closed point of $Y$ and a node.
\end{enumerate}

\label{lemma-fully-faithful-cases}
Let $f : X \to S$ be a morphism of schemes. In the following
cases the functor (\ref{equation-descent-etale}) is fully faithful:
\begin{enumerate}
\item $f$ is surjective and universally closed
(e.g., finite, integral, or proper),
\item $f$ is surjective and universally open
(e.g., locally of finite presentation and flat, smooth, or etale),
\item $f$ is surjective, quasi-compact, and flat.
\end{enumerate}

\label{lemma-reflexive-torsion-free}
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$
be a coherent $\mathcal{O}_X$-module.
\begin{enumerate}
\item If $\mathcal{F}$ is reflexive, then $\mathcal{F}$ is torsion free.
\item The map $j : \mathcal{F} \longrightarrow \mathcal{F}^{**}$
is injective if and only if $\mathcal{F}$ is torsion free.
\end{enumerate}

\label{lemma-characterize-reflexive}
Let $R$ be a Noetherian domain. Let $M$ be a finite $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is reflexive,
\item there exists a short exact sequence $0 \to M \to F \to N \to 0$
with $F$ finite free and $N$ torsion free.
\end{enumerate}

\label{lemma-descending-property-closed-immersion}
The property $\mathcal{P}(f) =$``$f$ is a closed immersion''
is fpqc local on the base.

\label{lemma-check-exactness-fibre-product}
Let $\mathcal{A}$ be an abelian category. Let $f:x\to y$ and $g:y\to z$ 
be morphisms with $g\circ f=0$. Then, the following statements are equivalent:
\begin{enumerate}
\item The sequence $x\overset{f}\to y\overset{g}\to z$ is exact.
\item For every $h:w\to y$ with $g\circ h=0$ there exist an object $v$, 
an epimorphism $k:v\to w$ and a morphism $l:v\to x$ with $h\circ k=f\circ l$.
\end{enumerate}

\label{lemma-descending-property-dominant}
The property $\mathcal{P}(f) =$``$f$ is quasi-compact and dominant''
is fpqc local on the base.

\label{lemma-image-of-quasi-compact}
\begin{slogan}
Sheaf surjections transmit quasi-compactness.
\end{slogan}
Let $\mathcal{C}$ be a site.
\begin{enumerate}
\item If $U \to V$ is a morphism of $\mathcal{C}$ such that
$h_U^\# \to h_V^\#$ is surjective and $U$ is quasi-compact, then
$V$ is quasi-compact.
\item If $\mathcal{F} \to \mathcal{G}$ is a surjection of sheaves
of sets and $\mathcal{F}$ is quasi-compact, then $\mathcal{G}$
is quasi-compact.
\end{enumerate}

\label{lemma-valuation-ring-flat-essentially-finite-type}
Let $A$ be a valuation ring. Let $A \to B$ be a local homomorphism
which is essentially of finite type. Let $M$ be a finite $B$-module.
\begin{enumerate}
\item If $B$ is flat over $A$, then $B$ is essentially of finite
presentation over $A$.
\item If $M$ is flat as an $A$-module, then $M$ is finitely presented
as a $B$-module.
\end{enumerate}

\label{lemma-open-subscheme-UFD}
Let $R$ be a UFD. The Picard groups of the following are
trivial.
\begin{enumerate}
\item $\Spec(R)$ and any open subscheme of it.
\item $\mathbf{A}^n_R = \Spec(R[x_1, \ldots, x_n])$ and any open subscheme
of it.
\end{enumerate}
In particular, the Picard group of any open subscheme of affine
$n$-space $\mathbf{A}^n_k$ over a field $k$ is trivial.

\label{lemma-direct-sum-from-product-colimit}
Let $\mathcal{I}$ be a category. Let $\mathcal{A}$ be an additive, Karoubian
category. Let $F : \mathcal{I} \to \mathcal{A}$ and
$G : \mathcal{I} \to \mathcal{A}$ be functors. The following are equivalent
\begin{enumerate}
\item $\colim_\mathcal{I} F \oplus G$ exists, and
\item $\colim_\mathcal{I} F$ and $\colim_\mathcal{I} G$ exist.
\end{enumerate}
In this case $\colim_\mathcal{I} F \oplus G =
\colim_\mathcal{I} F \oplus \colim_\mathcal{I} G$.

\label{lemma-open-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is open''
is fppf local on the source.

\label{lemma-characterize-geometrically-irreducible}
\begin{slogan}
Geometric irreducibility can be tested over a separable algebraic
closure of the base field.
\end{slogan}
Let $k$ be a field. Let $X$ be a scheme over $k$.
The following are equivalent:
\begin{enumerate}
\item $X$ is geometrically irreducible over $k$,
\item for every finite separable field extension $k'/k$
the scheme $X_{k'}$ is irreducible, and
\item $X_{\overline{k}}$ is irreducible, where $k \subset \overline{k}$
is a separable algebraic closure of $k$.
\end{enumerate}

statement:
Let $\mathcal{D}$ be a triangulated category.
Let $\mathcal{D}' \subset \mathcal{D}$ be a full triangulated
subcategory. Set
\begin{equation}

S =
\left\{
\begin{matrix}
f \in \text{Arrows}(\mathcal{D})
\text{ such that there exists a distinguished triangle }\\
(X, Y, Z, f, g, h) \text{ of }\mathcal{D}\text{ with }
Z\text{ isomorphic to an object of }\mathcal{D}'
\end{matrix}
\right\}
\end{equation}
Then $S$ is a multiplicative system compatible with the triangulated
structure on $\mathcal{D}$. In this situation the following are equivalent
\begin{enumerate}
\item $S$ is a saturated multiplicative system,
\item $\mathcal{D}'$ is a saturated triangulated subcategory.
\end{enumerate}

statement_tex:
\label{lemma-construct-multiplicative-system}
Let $\mathcal{D}$ be a triangulated category.
Let $\mathcal{D}' \subset \mathcal{D}$ be a full triangulated
subcategory. Set
\begin{equation}
\label{equation-multiplicative-system}
S =
\left\{
\begin{matrix}
f \in \text{Arrows}(\mathcal{D})
\text{ such that there exists a distinguished triangle }\\
(X, Y, Z, f, g, h) \text{ of }\mathcal{D}\text{ with }
Z\text{ isomorphic to an object of }\mathcal{D}'
\end{matrix}
\right\}
\end{equation}
Then $S$ is a multiplicative system compatible with the triangulated
structure on $\mathcal{D}$. In this situation the following are equivalent
\begin{enumerate}
\item $S$ is a saturated multiplicative system,
\item $\mathcal{D}'$ is a saturated triangulated subcategory.
\end{enumerate}

\label{lemma-epimorphism-universal-abelian-category}
Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item If $x \to y$ is surjective, then for every $z \to y$ the
projection $x \times_y z \to z$ is surjective.
\item If $x \to y$ is injective, then for every $x \to z$ the
morphism $z \to z \amalg_x y$ is injective.
\end{enumerate}

statement:
Let $f : x \to y$ be a morphism in an abelian category $\mathcal{A}$. Then
\begin{enumerate}
\item $f$ is injective if and only if $f$ is a monomorphism,
\item $f$ is surjective if and only if $f$ is an epimorphism, and
\item $f$ is an isomorphism if and only if $f$ is injective and surjective.
\end{enumerate}

statement_tex:
\label{lemma-characterize-injective}
Let $f : x \to y$ be a morphism in an abelian category $\mathcal{A}$. Then
\begin{enumerate}
\item $f$ is injective if and only if $f$ is a monomorphism,
\item $f$ is surjective if and only if $f$ is an epimorphism, and
\item $f$ is an isomorphism if and only if $f$ is injective and surjective.
\end{enumerate}

statement:
Let $f : A \to B$ be an unramified morphism of local rings.
Then there exist $f, g \in A[t]$ such that
\begin{enumerate}
\item $B' = A[t]_g/(f)$ is standard \'etale -- see (a) and (b) above, and
\item $B$ is isomorphic to a quotient of a localization of $B'$ at a prime.
\end{enumerate}

statement_tex:
\label{theorem-structure-unramified}
Let $f : A \to B$ be an unramified morphism of local rings.
Then there exist $f, g \in A[t]$ such that
\begin{enumerate}
\item $B' = A[t]_g/(f)$ is standard \'etale -- see (a) and (b) above, and
\item $B$ is isomorphic to a quotient of a localization of $B'$ at a prime.
\end{enumerate}

\label{lemma-locally-quasi-finite-etale-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally quasi-finite''
is \'etale local on the source.

\label{lemma-relative-regular-immersion-algebra}
Let $A \to B$ and $A \to A'$ be ring maps. Set $B' = B \otimes_A A'$.
Let $f_1, \ldots, f_r \in B$. Assume $B/(f_1, \ldots, f_r)B$ is flat over $A$
\begin{enumerate}
\item If $f_1, \ldots, f_r$ is a quasi-regular sequence, then
the image in $B'$ is a quasi-regular sequence.
\item If $f_1, \ldots, f_r$ is a $H_1$-regular sequence, then
the image in $B'$ is a $H_1$-regular sequence.
\end{enumerate}

\label{lemma-independence-of-generators}
Let $R$ be a ring. Let $I$ be an ideal generated by $f_1, \ldots, f_r \in R$.
\begin{enumerate}
\item If $I$ can be generated by a quasi-regular sequence of length $r$,
then $f_1, \ldots, f_r$ is a quasi-regular sequence.
\item If $I$ can be generated by an $H_1$-regular sequence of length $r$,
then $f_1, \ldots, f_r$ is an $H_1$-regular sequence.
\item If $I$ can be generated by a Koszul-regular sequence of length $r$,
then $f_1, \ldots, f_r$ is a Koszul-regular sequence.
\end{enumerate}

statement:
\begin{reference}
\cite[Expose I, Theorem 9.5 part (i)]{SGA1}
\end{reference}
Let $A$, $B$ be Noetherian local rings.
Let $f : A \to B$ be an \'etale homomorphism of local rings.
Then $A$ is a normal domain if and only if $B$ is so.

statement_tex:
\label{proposition-etale-normal}
\begin{reference}
\cite[Expose I, Theorem 9.5 part (i)]{SGA1}
\end{reference}
Let $A$, $B$ be Noetherian local rings.
Let $f : A \to B$ be an \'etale homomorphism of local rings.
Then $A$ is a normal domain if and only if $B$ is so.

statement:
\begin{reference}
\cite[Theorem 3]{Nagata-Finitely}
\end{reference}
Let $A$ be a valuation ring. Let $A \to B$ be a ring map of finite type.
Let $M$ be a finite $B$-module.
\begin{enumerate}
\item If $B$ is flat over $A$, then $B$ is a finitely presented $A$-algebra.
\item If $M$ is flat as an $A$-module, then $M$ is finitely presented
as a $B$-module.
\end{enumerate}

statement_tex:
\label{lemma-flat-finite-type-valuation-ring-finite-presentation}
\begin{reference}
\cite[Theorem 3]{Nagata-Finitely}
\end{reference}
Let $A$ be a valuation ring. Let $A \to B$ be a ring map of finite type.
Let $M$ be a finite $B$-module.
\begin{enumerate}
\item If $B$ is flat over $A$, then $B$ is a finitely presented $A$-algebra.
\item If $M$ is flat as an $A$-module, then $M$ is finitely presented
as a $B$-module.
\end{enumerate}

\label{lemma-inseparable-deg-p-smooth}
Let $k$ be a field of characteristic $p > 0$. Let $X$ be a variety over $k$.
The following are equivalent
\begin{enumerate}
\item $X^{(p)}$ is reduced,
\item $X$ is geometrically reduced,
\item there is a nonempty open $U \subset X$ smooth over $k$.
\end{enumerate}
In this case $X^{(p)}$ is a variety over $k$ and $F_{X/k} : X \to X^{(p)}$
is a finite dominant morphism of degree $p^{\dim(X)}$.

\label{lemma-dedekind-torsion-free-flat}
Let $A$ be a Dedekind domain (for example a discrete valuation ring
or more generally a PID).
\begin{enumerate}
\item An $A$-module is flat if and only if it is torsion free.
\item A finite torsion free $A$-module is finite locally free.
\item A finite torsion free $A$-module is finite free if
$A$ is a PID.
\end{enumerate}

\label{lemma-descending-property-isomorphism}
The property $\mathcal{P}(f) =$``$f$ is an isomorphism''
is fpqc local on the base.

\label{lemma-reflexive-over-regular-dim-2}
Let $X$ be a regular scheme of dimension $\leq 2$.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item $\mathcal{F}$ is finite locally free.
\end{enumerate}

\label{lemma-koszul-regular-H1-regular}
A $M$-Koszul-regular sequence is $M$-$H_1$-regular.
A Koszul-regular sequence is $H_1$-regular.

\label{lemma-image-connected-component}
\begin{reference}
Email from Ofer Gabber dated June 4, 2016
\end{reference}
Let $K/k$ be an extension of fields. Let $X$ be a scheme over $k$.
Denote $p : X_K \to X$ the projection morphism.
Let $\overline{T} \subset X_K$ be a connected component.
Then $p(\overline{T})$ is a connected component of $X$.

statement:
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$
be a coherent $\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item for each $x \in X$ one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x$ is a reflexive $\mathcal{O}_{X, x}$-module, or
\item $\text{depth}(\mathcal{F}_x) \geq 2$.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-reflexive-depth-2}
Let $X$ be an integral locally Noetherian scheme. Let $\mathcal{F}$
be a coherent $\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is reflexive,
\item for each $x \in X$ one of the following happens
\begin{enumerate}
\item $\mathcal{F}_x$ is a reflexive $\mathcal{O}_{X, x}$-module, or
\item $\text{depth}(\mathcal{F}_x) \geq 2$.
\end{enumerate}
\end{enumerate}

\label{lemma-regular-section-structure-sheaf}
Let $X$ be a locally ringed space. Let $f \in \Gamma(X, \mathcal{O}_X)$.
The following are equivalent:
\begin{enumerate}
\item $f$ is a regular section, and
\item for any $x \in X$ the image $f \in \mathcal{O}_{X, x}$
is a nonzerodivisor.
\end{enumerate}
If $X$ is a scheme these are also equivalent to
\begin{enumerate}
\item[(3)] for any affine open $\Spec(A) = U \subset X$
the image $f \in A$ is a nonzerodivisor,
\item[(4)] there exists an affine open covering
$X = \bigcup \Spec(A_i)$ such that
the image of $f$ in $A_i$ is a nonzerodivisor for all $i$.
\end{enumerate}

\label{lemma-four-lemma}
Let $\mathcal{A}$ be an abelian category. Let
$$
\xymatrix{
w \ar[r] \ar[d]^\alpha & x \ar[r] \ar[d]^\beta & y \ar[r] \ar[d]^\gamma &
z \ar[d]^\delta \\
w' \ar[r] & x' \ar[r] & y' \ar[r] & z'
}
$$
be a commutative diagram with exact rows.
\begin{enumerate}
\item If $\alpha, \gamma$ are surjective and $\delta$ is injective, then
$\beta$ is surjective.
\item If $\beta, \delta$ are injective and $\alpha$ is surjective, then
$\gamma$ is injective.
\end{enumerate}

\label{lemma-rank-tensor}
Let $R$ be a domain. Let $M$ and $N$ be $R$-modules.
\begin{enumerate}
\item The rank of $M \otimes_R N$ is the product of the
ranks of $M$ and $N$.
\item If $M$ is a finitely presented $R$-module, then
the rank of $\Hom_R(M, N)$ is the product of the
ranks of $M$ and $N$.
\end{enumerate}

\label{lemma-topology-basic}
Let $\mathcal{C}$ be a category.
Let $J$ be a topology on $\mathcal{C}$.
Let $U \in \Ob(\mathcal{C})$.
\begin{enumerate}
\item Finite intersections of elements of $J(U)$ are in $J(U)$.
\item If $S \in J(U)$ and $S' \supset S$, then $S' \in J(U)$.
\end{enumerate}

statement:
Let $I \subset J \subset A$ be ideals of a ring $A$.
The following are equivalent
\begin{enumerate}
\item $(A, I)$ and $(A/I, J/I)$ are henselian pairs, and
\item $(A, J)$ is an henselian pair.
\end{enumerate}

statement_tex:
\label{lemma-henselian-henselian-pair}
Let $I \subset J \subset A$ be ideals of a ring $A$.
The following are equivalent
\begin{enumerate}
\item $(A, I)$ and $(A/I, J/I)$ are henselian pairs, and
\item $(A, J)$ is an henselian pair.
\end{enumerate}

\label{lemma-inverse-systems-abelian}
Let $\mathcal{C}$ be a category.
\begin{enumerate}
\item If $\mathcal{C}$ is an additive category, then the category
of inverse systems with values in $\mathcal{C}$ is an additive category.
\item If $\mathcal{C}$ is an abelian category, then the category
of inverse systems with values in $\mathcal{C}$ is an abelian category.
A sequence $(K_i) \to (L_i) \to (M_i)$ of inverse systems
is exact if and only if each $K_i \to L_i \to N_i$ is exact.
\end{enumerate}

\label{lemma-descending-property-integral}
The property $\mathcal{P}(f) =$``$f$ is integral''
is fpqc local on the base.

\label{lemma-quasi-compact}
Let $\mathcal{C}$ be a site. Let $U$ be an object of $\mathcal{C}$.
The following are equivalent
\begin{enumerate}
\item $U$ is quasi-compact, and
\item for every surjection of sheaves
$\coprod_{i \in I} \mathcal{F}_i \to h_U^\#$
there is a finite subset $J \subset I$ such that
$\coprod_{i \in J} \mathcal{F}_i \to h_U^\#$ is surjective.
\end{enumerate}

\label{lemma-open-subtopos}
Let $\mathcal{C}$ be a site. Let $\mathcal{F}$ be a sheaf on
$\mathcal{C}$. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is a subobject of the final object of
$\Sh(\mathcal{C})$, and
\item the topos $\Sh(\mathcal{C})/\mathcal{F}$ is a subtopos of
$\Sh(\mathcal{C})$.
\end{enumerate}

\label{lemma-injective-tangent-spaces-unramified}
Let $f : X \to Y$ be a morphism of schemes locally of finite type over a
base scheme $S$. Let $x \in X$ be a point. Set $y = f(x)$ and assume
that $\kappa(y) = \kappa(x)$. Then the following are equivalent
\begin{enumerate}
\item $\text{d}f : T_{X/S, x} \longrightarrow T_{Y/S, y}$ is injective, and
\item $f$ is unramified at $x$.
\end{enumerate}

\label{lemma-universal-effective-epimorphism-surjective}
Let $\{f_i : X_i \to X\}_{i \in I}$ be a family of morphisms of schemes.
\begin{enumerate}
\item If the family is universal effective
epimorphism in the category of schemes, then $\coprod f_i$ is surjective.
\item If $X$ and $X_i$ are affine and the family is a universal effective
epimorphism in the category of affine schemes, then
$\coprod f_i$ is surjective.
\end{enumerate}

\label{lemma-descending-property-locally-finite-type}
The property $\mathcal{P}(f) =$``$f$ is locally of finite type''
is fpqc local on the base.

\label{lemma-morphisms-equal-up-to-homotopy-projective}
Let $\mathcal{A}$ be an abelian category. Consider a solid diagram
$$
\xymatrix{
K^\bullet & L^\bullet \ar[l]^\alpha \\
P^\bullet \ar[u] \ar@{-->}[ru]_{\beta_i}
}
$$
where $P^\bullet$ is bounded above and consists of projective
objects, and $\alpha$ is a quasi-isomorphism.
Any two morphisms $\beta_1, \beta_2$ making the diagram commute
up to homotopy are homotopic.

statement:
Let $\mathcal{D}$ be a pre-triangulated category.
Let $I$ be a set.
\begin{enumerate}
\item Let $X_i$, $i \in I$ be a family of objects of $\mathcal{D}$.
\begin{enumerate}
\item If $\prod X_i$ exists, then $(\prod X_i)[1] = \prod X_i[1]$.
\item If $\bigoplus X_i$ exists, then $(\bigoplus X_i)[1] = \bigoplus X_i[1]$.
\end{enumerate}
\item Let $X_i \to Y_i \to Z_i \to X_i[1]$ be a family of distinguished
triangles of $\mathcal{D}$.
\begin{enumerate}
\item If $\prod X_i$, $\prod Y_i$, $\prod Z_i$ exist, then
$\prod X_i \to \prod Y_i \to \prod Z_i \to \prod X_i[1]$
is a distinguished triangle.
\item If $\bigoplus X_i$, $\bigoplus Y_i$,
$\bigoplus Z_i$ exist, then
$\bigoplus X_i \to \bigoplus Y_i \to \bigoplus Z_i \to \bigoplus X_i[1]$
is a distinguished triangle.
\end{enumerate}
\end{enumerate}

statement_tex:
\label{lemma-products-sums-shifts-triangles}
Let $\mathcal{D}$ be a pre-triangulated category.
Let $I$ be a set.
\begin{enumerate}
\item Let $X_i$, $i \in I$ be a family of objects of $\mathcal{D}$.
\begin{enumerate}
\item If $\prod X_i$ exists, then $(\prod X_i)[1] = \prod X_i[1]$.
\item If $\bigoplus X_i$ exists, then $(\bigoplus X_i)[1] = \bigoplus X_i[1]$.
\end{enumerate}
\item Let $X_i \to Y_i \to Z_i \to X_i[1]$ be a family of distinguished
triangles of $\mathcal{D}$.
\begin{enumerate}
\item If $\prod X_i$, $\prod Y_i$, $\prod Z_i$ exist, then
$\prod X_i \to \prod Y_i \to \prod Z_i \to \prod X_i[1]$
is a distinguished triangle.
\item If $\bigoplus X_i$, $\bigoplus Y_i$,
$\bigoplus Z_i$ exist, then
$\bigoplus X_i \to \bigoplus Y_i \to \bigoplus Z_i \to \bigoplus X_i[1]$
is a distinguished triangle.
\end{enumerate}
\end{enumerate}

\label{lemma-higher-direct-images-compose}
\begin{slogan}
The total derived functor of a composition is the
composition of the total derived functors.
\end{slogan}
Let $f : X \to Y$ and $g : Y \to Z$ be morphisms of ringed spaces.
In this case $Rg_* \circ Rf_* = R(g \circ f)_*$ as functors
from $D^{+}(X) \to D^{+}(Z)$.

\label{lemma-colimit-abelian-category}
Let $\mathcal{A}$ be an abelian category.
All finite limits and finite colimits exist in $\mathcal{A}$.

statement:
Let $f : (X, \mathcal{O}_X) \to (Y, \mathcal{O}_Y)$
be a morphism of ringed spaces. The relative cup product of
Remark \ref{remark-cup-product} is associative in the sense that
the diagram
$$
\xymatrix{
Rf_*K \otimes_{\mathcal{O}_Y}^\mathbf{L}
Rf_*L \otimes_{\mathcal{O}_Y}^\mathbf{L}
Rf_*M \ar[r] \ar[d] &
Rf_*(K \otimes_{\mathcal{O}_X}^\mathbf{L} L)
\otimes_{\mathcal{O}_Y}^\mathbf{L} Rf_*M \ar[d] \\
Rf_*K \otimes_{\mathcal{O}_Y}^\mathbf{L}
Rf_*(L \otimes_{\mathcal{O}_X}^\mathbf{L} M) \ar[r] &
Rf_*(K \otimes_{\mathcal{O}_X}^\mathbf{L} 
L \otimes_{\mathcal{O}_X}^\mathbf{L} M)
}
$$
is commutative in $D(\mathcal{O}_Y)$ for all $K, L, M$ in $D(\mathcal{O}_X)$.

statement_tex:
\label{lemma-cup-product-associative}
Let $f : (X, \mathcal{O}_X) \to (Y, \mathcal{O}_Y)$
be a morphism of ringed spaces. The relative cup product of
Remark \ref{remark-cup-product} is associative in the sense that
the diagram
$$
\xymatrix{
Rf_*K \otimes_{\mathcal{O}_Y}^\mathbf{L}
Rf_*L \otimes_{\mathcal{O}_Y}^\mathbf{L}
Rf_*M \ar[r] \ar[d] &
Rf_*(K \otimes_{\mathcal{O}_X}^\mathbf{L} L)
\otimes_{\mathcal{O}_Y}^\mathbf{L} Rf_*M \ar[d] \\
Rf_*K \otimes_{\mathcal{O}_Y}^\mathbf{L}
Rf_*(L \otimes_{\mathcal{O}_X}^\mathbf{L} M) \ar[r] &
Rf_*(K \otimes_{\mathcal{O}_X}^\mathbf{L} 
L \otimes_{\mathcal{O}_X}^\mathbf{L} M)
}
$$
is commutative in $D(\mathcal{O}_Y)$ for all $K, L, M$ in $D(\mathcal{O}_X)$.

\label{lemma-reflexive-torsion-free}
Let $R$ be a domain and let $M$ be an $R$-module.
\begin{enumerate}
\item If $M$ is reflexive, then $M$ is torsion free.
\item If $M$ is finite, then the kernel and cokernel of
$j : M \to \Hom_R(\Hom_R(M, R), R)$ are torsion modules.
\item If $M$ is finite, then $j$ is injective
if and only if $M$ is torsion free.
\end{enumerate}

statement:
For any ring $A$ there exists an extension $A \subset B$ such that
\begin{enumerate}
\item $B$ is a filtered colimit of finite free $A$-algebras,
\item $B$ is free as an $A$-module, and
\item $B$ is absolutely integrally closed.
\end{enumerate}

statement_tex:
\label{lemma-construct-absolute-integral-closure}
For any ring $A$ there exists an extension $A \subset B$ such that
\begin{enumerate}
\item $B$ is a filtered colimit of finite free $A$-algebras,
\item $B$ is free as an $A$-module, and
\item $B$ is absolutely integrally closed.
\end{enumerate}

\label{lemma-when-jshriek-compact}
Let $X$ be a ringed space. Let $j : U \to X$ be the
inclusion of an open. The $\mathcal{O}_X$-module $j_!\mathcal{O}_U$ is a
compact object of $D(\mathcal{O}_X)$ if there exists an integer $d$ such that
\begin{enumerate}
\item $H^p(U, \mathcal{F}) = 0$ for all $p > d$, and
\item the functors $\mathcal{F} \mapsto H^p(U, \mathcal{F})$
commute with direct sums.
\end{enumerate}

statement:
Let $S$ be a scheme. Let $(G, m, e, i)$ be a group scheme over $S$.
\begin{enumerate}
\item A closed subscheme $H \subset G$ is a closed subgroup scheme
if and only if $e : S \to G$, $m|_{H \times_S H} : H \times_S H \to G$,
and $i|_H : H \to G$ factor through $H$.
\item An open subscheme $H \subset G$ is an open subgroup scheme
if and only if $e : S \to G$, $m|_{H \times_S H} : H \times_S H \to G$,
and $i|_H : H \to G$ factor through $H$.
\end{enumerate}

statement_tex:
\label{lemma-closed-subgroup-scheme}
Let $S$ be a scheme. Let $(G, m, e, i)$ be a group scheme over $S$.
\begin{enumerate}
\item A closed subscheme $H \subset G$ is a closed subgroup scheme
if and only if $e : S \to G$, $m|_{H \times_S H} : H \times_S H \to G$,
and $i|_H : H \to G$ factor through $H$.
\item An open subscheme $H \subset G$ is an open subgroup scheme
if and only if $e : S \to G$, $m|_{H \times_S H} : H \times_S H \to G$,
and $i|_H : H \to G$ factor through $H$.
\end{enumerate}

\label{lemma-descending-property-universally-closed}
The property $\mathcal{P}(f) =$``$f$ is universally closed''
is fpqc local on the base.

\label{lemma-products-homotopy}
Let $\mathcal{C}$ be a category. Let $T$ be a set. For $t \in T$
let $X_t$, $Y_t$ be simplicial objects of $\mathcal{C}$. Assume
$X = \prod_{t \in T} X_t$ and $Y = \prod_{t \in T} Y_t$ exist.
\begin{enumerate}
\item If $X_t$ and $Y_t$ are homotopy equivalent for all $t \in T$
and $T$ is finite, then $X$ and $Y$ are homotopy equivalent.
\end{enumerate}
For $t \in T$ let $a_t, b_t : X_t \to Y_t$ be morphisms.
Set $a = \prod a_t : X \to Y$ and $b = \prod b_t : X \to Y$.
\begin{enumerate}
\item[(2)] If there exists a homotopy from $a_t$ to $b_t$ for
all $t \in T$, then there exists a homotopy from $a$ to $b$.
\item[(3)] If $T$ is finite and $a_t, b_t : X_t \to Y_t$ for $t \in T$
are homotopic, then $a$ and $b$ are homotopic.
\end{enumerate}

\label{lemma-local-rings-UFD-c1-bijective}
Let $X$ be a locally Noetherian integral scheme. Consider the map
(\ref{equation-c1}) $\Pic(X) \to \text{Cl}(X)$.
The following are equivalent
\begin{enumerate}
\item the local rings of $X$ are UFDs, and
\item $X$ is normal and $\Pic(X) \to \text{Cl}(X)$
is surjective.
\end{enumerate}
In this case $\Pic(X) \to \text{Cl}(X)$ is an isomorphism.

statement:
Let $A$ be absolutely integrally closed.
\begin{enumerate}
\item Any quotient ring $A/I$ of $A$ is absolutely integrally closed.
\item Any localization $S^{-1}A$ is absolutely integrally closed.
\end{enumerate}

statement_tex:
\label{lemma-absolutely-integrally-closed-quotient-localization}
Let $A$ be absolutely integrally closed.
\begin{enumerate}
\item Any quotient ring $A/I$ of $A$ is absolutely integrally closed.
\item Any localization $S^{-1}A$ is absolutely integrally closed.
\end{enumerate}

\label{lemma-locally-finite-type-fppf-local-source}
The property $\mathcal{P}(f)=$``$f$ is locally of finite type''
is fppf local on the source.

\label{lemma-tor-amplitude-stalk}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $E$ be an object of $D(\mathcal{O}_X)$.
Let $a, b \in \mathbf{Z}$ with $a \leq b$. The following are equivalent
\begin{enumerate}
\item $E$ has tor-amplitude in $[a, b]$.
\item for every $x \in X$ the object $E_x$ of $D(\mathcal{O}_{X, x})$
has tor-amplitude in $[a, b]$.
\end{enumerate}

\label{lemma-sieve-sheafification}
Let $\mathcal{C}$ be a category endowed with a topology $J$.
Let $U$ be an object of $\mathcal{C}$.
Let $S$ be a sieve on $U$. The following are equivalent
\begin{enumerate}
\item The sieve $S$ is a covering sieve.
\item The sheafification $S^\# \to h_U^\#$
of the map $S \to h_U$ is an isomorphism.
\end{enumerate}

\label{lemma-descending-property-finite}
The property $\mathcal{P}(f) =$``$f$ is finite''
is fpqc local on the base.

\label{lemma-play-with-topologies}
Let $\mathcal{C}$ be a category.
Let $\{J_i\}_{i\in I}$ be a set of topologies.
\begin{enumerate}
\item The rule $J(U) = \bigcap J_i(U)$ defines
a topology on $\mathcal{C}$.
\item There is a coarsest topology finer than
all of the topologies $J_i$.
\end{enumerate}

\label{lemma-weakly-associated-affine-open}
Let $X$ be a scheme. Let $\mathcal{F}$ be a quasi-coherent sheaf on $X$.
Let $\Spec(A) = U \subset X$ be an affine open, and set
$M = \Gamma(U, \mathcal{F})$.
Let $x \in U$, and let $\mathfrak p \subset A$ be the corresponding prime.
The following are equivalent
\begin{enumerate}
\item $\mathfrak p$ is weakly associated to $M$, and
\item $x$ is weakly associated to $\mathcal{F}$.
\end{enumerate}

\label{lemma-smooth-smooth-local-source}
The property $\mathcal{P}(f)=$``$f$ is smooth''
is smooth local on the source.

\label{lemma-locally-Noetherian-K}
Let $X$ be a locally Noetherian scheme.
\begin{enumerate}
\item For any $x \in X$ we have $\mathcal{S}_x \subset \mathcal{O}_{X, x}$
is the set of nonzerodivisors, and hence $\mathcal{K}_{X, x}$
is the total quotient ring of $\mathcal{O}_{X, x}$.
\item For any affine open $U \subset X$ the ring
$\mathcal{K}_X(U)$ equals the total quotient ring of $\mathcal{O}_X(U)$.
\end{enumerate}

\label{lemma-tor-strictly-pro-zero}
\begin{reference}
This is \cite[Lemma 9.9]{quillenhomology}; note that
the author forgot the word ``strict'' in the statement
although it was clearly intended.
\end{reference}
Let $A$ be a Noetherian ring. Let $I$ be an ideal of $A$.
Let $M$ be a finite $A$-module. For every $p > 0$ there exists a $c > 0$
such that $\text{Tor}_p^A(M, A/I^n) \to \text{Tor}_p^A(M, A/I^{n - c})$
is zero for all $n \geq c$.

\label{lemma-descending-property-monomorphism}
The property $\mathcal{P}(f) =$``$f$ is a monomorphism''
is fpqc local on the base.

\label{lemma-descending-property-affine}
The property $\mathcal{P}(f) =$``$f$ is affine''
is fpqc local on the base.

statement:
The diagram
\begin{equation}

\xymatrix@C=8pc{
S_1 \ar[r]^{\delta^1_1} &
S_2 \ar@<1ex>[r]^{\delta^2_2} \ar@<-1ex>[r]_{\delta^2_1} & 
S_3
}
\end{equation}
is a split equalizer.

statement_tex:
\label{lemma-equalizer-S}
The diagram
\begin{equation}
\label{equation-equalizer-S}
\xymatrix@C=8pc{
S_1 \ar[r]^{\delta^1_1} &
S_2 \ar@<1ex>[r]^{\delta^2_2} \ar@<-1ex>[r]_{\delta^2_1} & 
S_3
}
\end{equation}
is a split equalizer.

\label{proposition-generator-versus-classical-generator}
Let $\mathcal{D}$ be a triangulated category with direct sums.
Let $E$ be a compact object of $\mathcal{D}$.
The following are equivalent
\begin{enumerate}
\item $E$ is a classical generator for $\mathcal{D}_c$ and
$\mathcal{D}$ is compactly generated, and
\item $E$ is a generator for $\mathcal{D}$.
\end{enumerate}

\label{lemma-fitting-ideal-finite-locally-free}
Let $R$ be a ring. Let $M$ be a finite $R$-module. Let $r \geq 0$.
The following are equivalent
\begin{enumerate}
\item $M$ is finite locally free of rank $r$
(Algebra, Definition \ref{algebra-definition-locally-free}),
\item $\text{Fit}_{r - 1}(M) = 0$ and $\text{Fit}_r(M) = R$, and
\item $\text{Fit}_k(M) = 0$ for $k < r$ and $\text{Fit}_k(M) = R$
for $k \geq r$.
\end{enumerate}

\label{lemma-flat-tor-zero}
\begin{slogan}
Tor measures the deviation of flatness.
\end{slogan}
Let $(X, \mathcal{O}_X)$ be a ringed space.
Let $\mathcal{F}$ be an $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is a flat $\mathcal{O}_X$-module, and
\item $\text{Tor}_1^{\mathcal{O}_X}(\mathcal{F}, \mathcal{G}) = 0$
for every $\mathcal{O}_X$-module $\mathcal{G}$.
\end{enumerate}

\label{lemma-nodal-family-fpqc-local-target}
Let $f : X \to S$ be a morphism of schemes. Let $\{U_i \to S\}$
be an fpqc covering. The following are equivalent
\begin{enumerate}
\item $f$ is at-worst-nodal of relative dimension $1$,
\item each $X \times_S U_i \to U_i$ is at-worst-nodal of relative
dimension $1$.
\end{enumerate}
In other words, being at-worst-nodal of relative dimension $1$
is fpqc local on the target.

\label{lemma-regular-ideal-sheaf-quasi-coherent}
Any regular, Koszul-regular, $H_1$-regular, or quasi-regular sheaf
of ideals on a scheme is a finite type quasi-coherent sheaf of ideals.

\label{lemma-diagram-pull}
Let $S$ be a scheme.
Let $(U, R, s, t, c, e, i)$ be a groupoid over $S$.
The diagram
\begin{equation}
\label{equation-pull}
\xymatrix{
R \times_{t, U, t} R
\ar@<1ex>[r]^-{\text{pr}_1} \ar@<-1ex>[r]_-{\text{pr}_0}
\ar[d]_{(\text{pr}_0, c \circ (i, 1))} &
R \ar[r]^t \ar[d]^{\text{id}_R} &
U \ar[d]^{\text{id}_U} \\
R \times_{s, U, t} R
\ar@<1ex>[r]^-c \ar@<-1ex>[r]_-{\text{pr}_0} \ar[d]_{\text{pr}_1} &
R \ar[r]^t \ar[d]^s &
U \\
R \ar@<1ex>[r]^s \ar@<-1ex>[r]_t &
U
}
\end{equation}
is commutative. The two top rows are isomorphic via the vertical maps given.
The two lower left squares are cartesian.

\label{lemma-kernel-quotient}
Let $\mathcal{D}$ be a triangulated category.
Let $\mathcal{B}$ be a full triangulated subcategory.
The kernel of the quotient functor
$Q : \mathcal{D} \to \mathcal{D}/\mathcal{B}$
is the strictly full subcategory of $\mathcal{D}$ whose objects are
$$
\Ob(\Ker(Q)) =
\left\{
\begin{matrix}
Z \in \Ob(\mathcal{D})
\text{ such that there exists a }Z' \in \Ob(\mathcal{D}) \\
\text{ such that }Z \oplus Z'\text{ is isomorphic to an object of }\mathcal{B}
\end{matrix}
\right\}
$$
In other words it is the smallest strictly full saturated triangulated
subcategory of $\mathcal{D}$ containing $\mathcal{B}$.

\label{lemma-descending-property-flat}
The property $\mathcal{P}(f) =$``$f$ is flat''
is fpqc local on the base.

\label{lemma-descending-property-finite-type}
The property $\mathcal{P}(f) =$``$f$ is of finite type''
is fpqc local on the base.

\label{lemma-smooth-models}
Let $k$ be a field. Let $X$ be a geometrically irreducible curve over $k$.
For a field extension $K/k$ denote $Y_K$ a nonsingular projective model
of $(X_K)_{red}$.
\begin{enumerate}
\item If $X$ is proper, then $Y_K$ is the normalization of $X_K$.
\item There exists $K/k$ finite purely inseparable such that $Y_K$ is smooth.
\item Whenever $Y_K$ is smooth\footnote{Or even geometrically reduced.}
we have $H^0(Y_K, \mathcal{O}_{Y_K}) = K$.
\item Given a commutative diagram
$$
\xymatrix{
\Omega & K' \ar[l] \\
K \ar[u] & k \ar[l] \ar[u]
}
$$
of fields such that $Y_K$ and $Y_{K'}$ are smooth, then
$Y_\Omega = (Y_K)_\Omega = (Y_{K'})_\Omega$.
\end{enumerate}

\label{theorem-flat-is-quotient}
A faithfully flat quasi-compact morphism is a quotient map for
the Zariski topology.

\label{lemma-descending-property-regular-immersion}
The properties
\begin{enumerate}
\item[] $\mathcal{P}(f) =$``$f$ is a Koszul-regular immersion'',
\item[] $\mathcal{P}(f) =$``$f$ is an $H_1$-regular immersion'', and
\item[] $\mathcal{P}(f) =$``$f$ is a quasi-regular immersion''
\end{enumerate}
are fpqc local on the base.

\label{lemma-composition-strict}
Let $\mathcal{A}$ be an abelian category. Let $f : A \to B$, $g : B \to C$
be strict morphisms of filtered objects.
\begin{enumerate}
\item In general the composition $g \circ f$ is not strict.
\item If $g$ is injective, then $g \circ f$ is strict.
\item If $f$ is surjective, then $g \circ f$ is strict.
\end{enumerate}

\label{theorem-etale-radicial-open}
Let $f : X \to Y$ be a morphism of schemes.
The following are equivalent:
\begin{enumerate}
\item $f$ is an open immersion,
\item $f$ is universally injective and \'etale, and
\item $f$ is a flat monomorphism, locally of finite presentation.
\end{enumerate}

statement:
Let $k$ be a field. Let $X$, $Y$ be locally algebraic $k$-schemes.
\begin{enumerate}
\item For $z \in X \times Y$ lying over $(x, y)$ we have
$\dim_z(X \times Y) = \dim_x(X) + \dim_y(Y)$.
\item We have $\dim(X \times Y) = \dim(X) + \dim(Y)$.
\end{enumerate}

statement_tex:
\label{lemma-dimension-product-locally-algebraic}
\begin{slogan}
The dimension of the product is the sum of the dimensions.
\end{slogan}
Let $k$ be a field. Let $X$, $Y$ be locally algebraic $k$-schemes.
\begin{enumerate}
\item For $z \in X \times Y$ lying over $(x, y)$ we have
$\dim_z(X \times Y) = \dim_x(X) + \dim_y(Y)$.
\item We have $\dim(X \times Y) = \dim(X) + \dim(Y)$.
\end{enumerate}

statement:
Let $f : (X, \mathcal{O}_X) \to (Y, \mathcal{O}_Y)$ be a morphism
of ringed spaces. Let $\mathcal{K}^\bullet$ and $\mathcal{M}^\bullet$
be complexes of $\mathcal{O}_Y$-modules. The diagram
$$
\xymatrix{
Lf^*(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}^\mathbf{L}
\mathcal{M}^\bullet) \ar[r] \ar[d] &
Lf^*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}
\mathcal{M}^\bullet) \ar[d] \\
Lf^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_X}^\mathbf{L}
Lf^*\mathcal{M}^\bullet \ar[d] &
f^*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}
\mathcal{M}^\bullet) \ar[d] \\
f^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_X}^\mathbf{L}
f^*\mathcal{M}^\bullet \ar[r] &
\text{Tot}(f^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_X}
f^*\mathcal{M}^\bullet)
}
$$
commutes.

statement_tex:
\label{lemma-tensor-pull-compatibility}
Let $f : (X, \mathcal{O}_X) \to (Y, \mathcal{O}_Y)$ be a morphism
of ringed spaces. Let $\mathcal{K}^\bullet$ and $\mathcal{M}^\bullet$
be complexes of $\mathcal{O}_Y$-modules. The diagram
$$
\xymatrix{
Lf^*(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}^\mathbf{L}
\mathcal{M}^\bullet) \ar[r] \ar[d] &
Lf^*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}
\mathcal{M}^\bullet) \ar[d] \\
Lf^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_X}^\mathbf{L}
Lf^*\mathcal{M}^\bullet \ar[d] &
f^*\text{Tot}(\mathcal{K}^\bullet
\otimes_{\mathcal{O}_Y}
\mathcal{M}^\bullet) \ar[d] \\
f^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_X}^\mathbf{L}
f^*\mathcal{M}^\bullet \ar[r] &
\text{Tot}(f^*\mathcal{K}^\bullet \otimes_{\mathcal{O}_X}
f^*\mathcal{M}^\bullet)
}
$$
commutes.

\label{lemma-torsion-free-over-regular-dim-1}
Let $X$ be an integral regular scheme of dimension $\leq 1$.
Let $\mathcal{F}$ be a coherent $\mathcal{O}_X$-module.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is torsion free,
\item $\mathcal{F}$ is finite locally free.
\end{enumerate}

\label{lemma-geometrically-irreducible-self-product}
A scheme $X$ over a field $k$ is geometrically irreducible
over $k$ if and only if $X\times_k X$ is irreducible.

statement:
Let $X$ be a locally Noetherian scheme of dimension $\leq 1$.
The following are equivalent
\begin{enumerate}
\item $X$ is Cohen-Macaulay, and
\item $X$ has no embedded points.
\end{enumerate}

statement_tex:
\label{lemma-noetherian-dim-1-CM-no-embedded-points}
Let $X$ be a locally Noetherian scheme of dimension $\leq 1$.
The following are equivalent
\begin{enumerate}
\item $X$ is Cohen-Macaulay, and
\item $X$ has no embedded points.
\end{enumerate}

\label{lemma-compare-etale-zariski-flat}
In Lemma \ref{lemma-compare-sites} the morphism of ringed
sites $\text{id}_{small, \etale, Zar} : S_\etale \to S_{Zar}$ is flat.

\label{lemma-cone}
The cone on a morphism of strictly perfect complexes is
strictly perfect.

\label{lemma-characterize-geometrically-disconnected}
Let $k$ be a field.
Let $X$ be a scheme over $k$.
The following are equivalent
\begin{enumerate}
\item $X$ is geometrically connected,
\item for every finite separable field extension $k'/k$
the scheme $X_{k'}$ is connected.
\end{enumerate}

statement:
\begin{reference}
This is a particular case of \cite[Corollary]{McCoy}
\end{reference}
Let $R$ be a ring. Let $a_1, \ldots, a_n \in R$ be elements such
that $R \to R^{\oplus n}$, $x \mapsto (xa_1, \ldots, xa_n)$ is injective.
Then the element $\sum a_i t_i$ of the polynomial ring $R[t_1, \ldots, t_n]$
is a nonzerodivisor.

statement_tex:
\label{lemma-make-nonzero-divisor}
\begin{reference}
This is a particular case of \cite[Corollary]{McCoy}
\end{reference}
Let $R$ be a ring. Let $a_1, \ldots, a_n \in R$ be elements such
that $R \to R^{\oplus n}$, $x \mapsto (xa_1, \ldots, xa_n)$ is injective.
Then the element $\sum a_i t_i$ of the polynomial ring $R[t_1, \ldots, t_n]$
is a nonzerodivisor.

\label{lemma-finite-length}
Let $\mathcal{A}$ be an abelian category. Let $A$ be an object
of $\mathcal{A}$. The following are equivalent
\begin{enumerate}
\item $A$ is Artinian and Noetherian, and
\item there exists a filtration
$0 \subset A_1 \subset A_2 \subset \ldots \subset A_n = A$
by subobjects such that $A_i/A_{i - 1}$ is simple for $i = 1, \ldots, n$.
\end{enumerate}

\label{lemma-torsion-free-finite-noetherian-domain}
Let $R$ be a Noetherian domain. Let $M$ be a nonzero finite $R$-module.
The following are equivalent
\begin{enumerate}
\item $M$ is torsion free,
\item $M$ is a submodule of a finite free module,
\item $(0)$ is the only associated prime of $M$,
\item $(0)$ is in the support of $M$ and $M$ has property $(S_1)$, and
\item $(0)$ is in the support of $M$ and $M$ has no embedded associated prime.
\end{enumerate}

\label{lemma-number-of-branches}
Let $X$ be a scheme. Assume every quasi-compact open of $X$ has
finitely many irreducible components. Let $\nu : X^\nu \to X$
be the normalization of $X$. Let $x \in X$.
\begin{enumerate}
\item The number of branches of $X$ at $x$ is the number of
inverse images of $x$ in $X^\nu$.
\item The number of geometric branches of $X$ at $x$ is
$\sum_{\nu(x^\nu) = x} [\kappa(x^\nu) : \kappa(x)]_s$.
\end{enumerate}

\label{lemma-sheafification-exact}
The functor $\textit{PSh}(\mathcal{C}) \to \Sh(\mathcal{C})$,
$\mathcal{F} \mapsto \mathcal{F}^\#$ is exact.

\label{lemma-descending-property-universally-injective}
The property $\mathcal{P}(f) =$``$f$ is universally injective''
is fpqc local on the base.

\label{lemma-Sk-local-syntomic}
The property $\mathcal{P}(S) =$``$S$ is locally Noetherian and $(S_k)$''
is local in the syntomic topology.

\label{lemma-cone-pseudo-coherent}
Let $(X, \mathcal{O}_X)$ be a ringed space and $m \in \mathbf{Z}$.
Let $(K, L, M, f, g, h)$ be a distinguished triangle in $D(\mathcal{O}_X)$.
\begin{enumerate}
\item If $K$ is $(m + 1)$-pseudo-coherent and $L$ is $m$-pseudo-coherent
then $M$ is $m$-pseudo-coherent.
\item If $K$ and $M$ are $m$-pseudo-coherent, then $L$ is $m$-pseudo-coherent.
\item If $L$ is $(m + 1)$-pseudo-coherent and $M$
is $m$-pseudo-coherent, then $K$ is $(m + 1)$-pseudo-coherent.
\end{enumerate}

\label{lemma-Noetherian-local-fppf}
The property $\mathcal{P}(S) =$``$S$ is locally Noetherian'' is local
in the fppf topology.

\label{lemma-descending-property-syntomic}
The property $\mathcal{P}(f) =$``$f$ is syntomic''
is fpqc local on the base.

\label{lemma-cech-exact-presheaves}
The functor given by Equation (\ref{equation-cech-functor})
is an exact functor (see Homology, Lemma \ref{homology-lemma-exact-functor}).

\label{lemma-CM-local-syntomic}
The property $\mathcal{P}(S) =$``$S$ is Cohen-Macaulay''
is local in the syntomic topology.

\label{lemma-filtered}
Let $\mathcal{A}$ be an abelian category.
The category of filtered objects $\text{Fil}(\mathcal{A})$
has the following properties:
\begin{enumerate}
\item It is an additive category.
\item It has a zero object.
\item It has kernels and cokernels, images and coimages.
\item In general it is not an abelian category.
\end{enumerate}

\label{lemma-check-torsion-on-affines}
Let $X$ be an integral scheme. Let $\mathcal{F}$ be a quasi-coherent
$\mathcal{O}_X$-module. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is torsion free,
\item for $U \subset X$ affine open $\mathcal{F}(U)$
is a torsion free $\mathcal{O}(U)$-module.
\end{enumerate}

